ST.xhtml:p:
(*判断当前坐标是否大于初次设置的水平点*)
(*坐标大于水平点*)
IF nNearByCenterEnable = 1 THEN
  IF g_diUMachineCoordinate > g_dAngle THEN
    dInteger := LREAL_TO_LINT((g_diUMachineCoordinate - g_dAngle) / 360.0);
    dIntegerCoordA := LINT_TO_LREAL(dInteger * 360);
    IF g_diUMachineCoordinate - g_dAngle >= g_dAngle + dIntegerCoordA - g_diUMachineCoordinate THEN
      g_noCenterUCoorditate := g_dAngle + dIntegerCoordA;
    ELSE
      g_noCenterUCoorditate := g_dAngle;
    END_IF;
  ELSIF g_diUMachineCoordinate < g_dAngle THEN
    dInteger := LREAL_TO_LINT((g_dAngle - g_diUMachineCoordinate) / 360.0);
    dIntegerCoordA := LINT_TO_LREAL(dInteger * 360);
    dIntegerCoordB := LINT_TO_LREAL((dInteger + 1)*360);
    IF dInteger >= 1 THEN
      IF (g_dAngle - dIntegerCoordA) - g_diUMachineCoordinate >= g_diUMachineCoordinate - (g_dAngle - dIntegerCoordB) THEN
        g_noCenterUCoorditate := g_dAngle - dIntegerCoordB;
      ELSE
        g_noCenterUCoorditate := g_dAngle - dIntegerCoordA;
      END_IF;
    ELSE
      IF g_dAngle - g_diUMachineCoordinate >= g_diUMachineCoordinate - (g_dAngle - dIntegerCoordB) THEN
        g_noCenterUCoorditate := g_dAngle - dIntegerCoordB;
      ELSE
        g_noCenterUCoorditate := g_dAngle;
      END_IF;
    END_IF;
  END_IF;
ELSE
  g_noCenterUCoorditate := g_dAngle;
END_IF;
